package LFFC01;

public class LFFC31 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		 System.out.println("***********************************");
	        System.out.println("* Aluno: LUIZ FELIPE FREIRE DA CRUZ - RA 0023623 *");
	        System.out.println("* Classe LFFC31 - Contar de 1 a 10 com do-while *");
	        System.out.println("***********************************");

	        int i = 1;
	        
	        System.out.println("Contando de 1 a 10 (do-while):");
	        
	        do {
	            System.out.println(i);
	            i++;
	        } while (i <= 10);
	}

}
